random.seed(42)
found = False
selected = None
trials = 0
while trials < 10000:
    trials += 1
    selected = random.sample(possible_edges, 29)
    if not has_short_cycle(selected):
        found = True
        break

print("Found:", found, "after", trials, "trials")
if found:
    print("Edges:", sorted(selected))
else:
    print("Not found")

